param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$meta=Get-Content -Raw -LiteralPath (Join-Path $root 'developer.json')|ConvertFrom-Json;$target=[IO.Path]::GetFullPath($Path)
if(-not(Test-Path -LiteralPath $target -PathType Leaf)){throw 'Target .env file must already exist.'};$null=& git -C (Split-Path -Parent $target) check-ignore -q -- $target 2>$null;if($LASTEXITCODE-ne 0){throw 'Refusing to write RabbitMQ credentials to a file not ignored by Git.'}
$secret=Import-Clixml (Join-Path $root 'secrets\g5_ventas.clixml');$password=[Net.NetworkCredential]::new('', $secret).Password;$url="amqp://g5_ventas:$([uri]::EscapeDataString($password))@127.0.0.1:5673/g6-productos-ofertas";$lines=[Collections.Generic.List[string]]::new();foreach($line in [IO.File]::ReadAllLines($target)){if($line-notmatch'^\s*RABBITMQ_URL\s*='){$lines.Add($line)}};$lines.Add("RABBITMQ_URL=$url");[IO.File]::WriteAllLines($target,$lines,[Text.UTF8Encoding]::new($false));$password=$null;$secret.Dispose();Write-Output 'RABBITMQ_URL configured without displaying its value; confirm the .env remains ignored by Git.'
